import { Box, Container, Typography } from "@mui/material";

import MetricsDashboard from "./components/MetricsDashboard";

export default function App() {
  return (
    <Box
      sx={{
        minHeight: "100vh",
        background:
          "radial-gradient(circle at top left, rgba(59, 130, 246, 0.12), transparent 35%), linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%)",
        py: { xs: 4, md: 8 },
      }}
    >
      <Container maxWidth="lg">
        <Typography
          component="h1"
          sx={{
            color: "#0f172a",
            fontSize: { xs: "2rem", md: "3rem" },
            fontWeight: 800,
            letterSpacing: "-0.04em",
            mb: 1,
          }}
        >
          Usage Dashboard
        </Typography>
        <Typography
          sx={{
            color: "rgba(15, 23, 42, 0.72)",
            fontSize: { xs: "1rem", md: "1.1rem" },
            mb: 4,
            maxWidth: 720,
          }}
        >
          Live view of weekly Seamless credit consumption and enrichment
          throughput across the Dynamics pipeline.
        </Typography>
        <MetricsDashboard />
      </Container>
    </Box>
  );
}
